using System.ClientModel;
using System.ComponentModel;
using System.Net;
using System.Text;
using System.Text.Json;
using System.Text.RegularExpressions;
using Microsoft.Extensions.AI;
using OpenAI;

// ---------------------------------------------------------------------------
// Configuration
// ---------------------------------------------------------------------------
var openAiKey = Environment.GetEnvironmentVariable("OPENAI_API_KEY") ?? "";
var model = Environment.GetEnvironmentVariable("OPENAI_MODEL") ?? "gpt-4o-mini";

if (string.IsNullOrWhiteSpace(openAiKey))
{
    Console.Error.WriteLine("Set the OPENAI_API_KEY environment variable to run the agent.");
    return 1;
}

// ---------------------------------------------------------------------------
// Tools
// ---------------------------------------------------------------------------
var notebook = new Notebook();
var webSearch = new WebSearchTool();

var tools = new List<AITool>
{
    AIFunctionFactory.Create(webSearch.Search),
    AIFunctionFactory.Create(notebook.AddNote),
    AIFunctionFactory.Create(notebook.GetNotes),
};

// ---------------------------------------------------------------------------
// Chat client with automatic function-calling
// ---------------------------------------------------------------------------
IChatClient client = new OpenAIClient(new ApiKeyCredential(openAiKey))
    .GetChatClient(model)
    .AsIChatClient()
    .AsBuilder()
    .UseFunctionInvocation()
    .Build();

var chatOptions = new ChatOptions { Tools = [.. tools] };

// ---------------------------------------------------------------------------
// System prompt
// ---------------------------------------------------------------------------
const string SystemPrompt = """
    You are a research agent. The user gives you a topic and you research it
    thoroughly by searching the web multiple times with different queries.

    Your workflow:
    1. Break the topic into 2-4 search queries that cover different angles.
    2. For each query, call the web_search tool.
    3. After each search, save the most important findings using add_note.
    4. After all searches are done, call get_notes to review everything.
    5. Write a well-structured summary with sections, citing sources where possible.

    Be thorough but concise. Use Markdown formatting in your final summary.
    """;

// ---------------------------------------------------------------------------
// Agent loop
// ---------------------------------------------------------------------------
Console.WriteLine("╔══════════════════════════════════════╗");
Console.WriteLine("║       AI Research Agent (v1.0)       ║");
Console.WriteLine("╚══════════════════════════════════════╝");
Console.WriteLine();
Console.Write("Enter a research topic: ");
var topic = Console.ReadLine();

if (string.IsNullOrWhiteSpace(topic))
{
    Console.Error.WriteLine("No topic provided.");
    return 1;
}

Console.WriteLine();
Console.WriteLine($"Researching: {topic}");
Console.WriteLine(new string('─', 50));
Console.WriteLine();

var messages = new List<ChatMessage>
{
    new(ChatRole.System, SystemPrompt),
    new(ChatRole.User, $"Research this topic and provide a detailed summary: {topic}"),
};

var response = await client.GetResponseAsync(messages, chatOptions);

Console.WriteLine(response.Text);
Console.WriteLine();
Console.WriteLine(new string('─', 50));
Console.WriteLine($"Research complete — {notebook.Count} note(s) collected.");

return 0;

