/// <summary>
/// Searches the web using Bing and returns a snippet of the top results.
/// </summary>
sealed class WebSearchTool
{
    private static readonly HttpClient Http = new()
    {
        DefaultRequestHeaders =
        {
            { "User-Agent", "Mozilla/5.0 (compatible; ResearchAgent/1.0)" },
            { "Accept-Language", "en-US,en;q=0.9" },
        },
        Timeout = TimeSpan.FromSeconds(15),
    };

    [Description("Search the web for a query and return relevant result snippets.")]
    public async Task<string> Search(
        [Description("The search query string")] string query)
    {
        Console.WriteLine($"  🔍 Searching: \"{query}\"");

        try
        {
            var encoded = WebUtility.UrlEncode(query);
            var url = $"https://html.duckduckgo.com/html/?q={encoded}";
            var html = await Http.GetStringAsync(url);

            var results = ParseDuckDuckGoResults(html);

            if (results.Count == 0)
                return $"No results found for '{query}'.";

            var sb = new StringBuilder();
            sb.AppendLine($"Search results for: {query}");
            sb.AppendLine();

            foreach (var (title, snippet, link) in results.Take(5))
            {
                sb.AppendLine($"- **{title}**");
                if (!string.IsNullOrEmpty(snippet))
                    sb.AppendLine($"  {snippet}");
                if (!string.IsNullOrEmpty(link))
                    sb.AppendLine($"  Source: {link}");
                sb.AppendLine();
            }

            return sb.ToString();
        }
        catch (Exception ex)
        {
            return $"Search failed for '{query}': {ex.Message}";
        }
    }

    private static List<(string Title, string Snippet, string Link)> ParseDuckDuckGoResults(string html)
    {
        var results = new List<(string, string, string)>();

        // Match result blocks from DuckDuckGo HTML-only endpoint
        var resultBlocks = Regex.Matches(html,
            @"<a[^>]+class=""result__a""[^>]*>(.*?)</a>.*?<a[^>]+class=""result__snippet""[^>]*>(.*?)</a>.*?<a[^>]+class=""result__url""[^>]*>(.*?)</a>",
            RegexOptions.Singleline | RegexOptions.IgnoreCase);

        if (resultBlocks.Count > 0)
        {
            foreach (Match m in resultBlocks)
            {
                var title = StripHtml(m.Groups[1].Value).Trim();
                var snippet = StripHtml(m.Groups[2].Value).Trim();
                var link = StripHtml(m.Groups[3].Value).Trim();
                if (!string.IsNullOrEmpty(title))
                    results.Add((title, snippet, link));
            }
        }
        else
        {
            // Fallback: try to grab any result__a links
            var titleMatches = Regex.Matches(html,
                @"<a[^>]+class=""result__a""[^>]*href=""([^""]+)""[^>]*>(.*?)</a>",
                RegexOptions.Singleline | RegexOptions.IgnoreCase);

            var snippetMatches = Regex.Matches(html,
                @"class=""result__snippet""[^>]*>(.*?)</",
                RegexOptions.Singleline | RegexOptions.IgnoreCase);

            for (int i = 0; i < titleMatches.Count; i++)
            {
                var title = StripHtml(titleMatches[i].Groups[2].Value).Trim();
                var link = titleMatches[i].Groups[1].Value.Trim();
                var snippet = i < snippetMatches.Count
                    ? StripHtml(snippetMatches[i].Groups[1].Value).Trim()
                    : "";
                if (!string.IsNullOrEmpty(title))
                    results.Add((title, snippet, link));
            }
        }

        return results;
    }

    private static string StripHtml(string html) =>
        Regex.Replace(WebUtility.HtmlDecode(
            Regex.Replace(html, @"<[^>]+>", " ")), @"\s+", " ");
}

/// <summary>
