sealed class Notebook
{
    private readonly List<(string Topic, string Content)> _notes = [];

    public int Count => _notes.Count;

    [Description("Save a research note. Use this to record important findings from searches.")]
    public string AddNote(
        [Description("Short label for the note (e.g. 'key dates', 'main arguments')")] string topic,
        [Description("The content of the note")] string content)
    {
        _notes.Add((topic, content));
        Console.WriteLine($"  📝 Note saved: \"{topic}\"");
        return $"Note #{_notes.Count} saved under '{topic}'.";
    }

    [Description("Retrieve all saved research notes to review before writing the summary.")]
    public string GetNotes()
    {
        if (_notes.Count == 0)
            return "No notes saved yet.";

        var sb = new StringBuilder();
        sb.AppendLine($"All research notes ({_notes.Count} total):");
        sb.AppendLine();

        for (int i = 0; i < _notes.Count; i++)
        {
            var (topic, content) = _notes[i];
            sb.AppendLine($"--- Note #{i + 1}: {topic} ---");
            sb.AppendLine(content);
            sb.AppendLine();
        }

        return sb.ToString();
    }
}

